import org.junit.Test;
import static org.junit.Assert.*;
import java.security.Signature;
import java.security.MessageDigest;

public class KeyPairTest {

    @Test
    public void canSign_DoesNotThrowException_WhenPublicAndPrivateKeysAreAvailable() {
        EdDSAPublicKey publicKey = new EdDSAPublicKey();
        EdDSAPrivateKey privateKey = new EdDSAPrivateKey();
        assertTrue(KeyPair.canSign(publicKey, privateKey));
    }

    @Test
    public void canSign_ThrowsException_WhenPublicAndPrivateKeysAreNotAvailable() {
        EdDSAPublicKey publicKey = null;
        EdDSAPrivateKey privateKey = null;
        assertFalse(KeyPair.canSign(publicKey, privateKey));
    }
}

public class KeyPairUtilTest {

    @Test
    public void fromSecretSeed_String_ThrowsException_WhenInputIsInvalid() {
        assertTrue(KeyPair.fromSecretSeed(null).equals(new KeyPair()));
        assertNotEquals(new KeyPair(), KeyPair.fromSecretSeed(""));
        assertNotEquals(new KeyPair(), KeyPair.fromSecretSeed(new String[]{"a", "b"}));
    }

    @Test
    public void fromPublic_BinaryData_ReturnsValidKeyPair() {
        byte[] publicKey = {1, 2, 3};
        assertTrue(KeyPair.fromPublicKey(publicKey).getPublicKey().equals(publicKey));
    }
}

public class KeyPairRandomnessTest {

    @Test
    public void random_ReturnsUniqueKeyPair_WithDifferentPublicAndPrivateKeys() {
        KeyPair keyPair1 = KeyPair.random();
        KeyPair keyPair2 = KeyPair.random();
        assertNotEquals(keyPair1.getPublicKey(), keyPair2.getPublicKey());
        assertTrue(keyPair1.canSign(keyPair1.getPublicKey()));
    }
}

public class KeyPairAccountingTest {

    @Test
    public void fromAccountId_ReturnsValidKeyPair_WithUniqueAccountId() {
        String accountId = "account-id-123";
        assertTrue(KeyPair.fromAccountId(accountId).getAccountId().equals(accountId));
    }

    @Test
    public void getPublic_BinaryData_ReturnsSamePublicKey() {
        byte[] publicKey = KeyPair.fromBip39Seed("bip39-seed", 1).getPublicKey();
        assertEquals(publicKey, KeyPair.fromPublicKey(publicKey));
    }
}

public class SignatureVerificationTest {

    @Test
    public void verify_DoesNotThrowException_WhenSignatureIsValid() {
        byte[] data = {1, 2, 3};
        byte[] signature = {4, 5, 6};
        assertTrue(KeyPair.fromBip39Seed("bip39-seed", 1).verify(data, signature));
    }

    @Test
    public void verify_ThrowsException_WhenSignatureIsInvalid() {
        byte[] data = {1, 2, 3};
        byte[] signature = {4, 5, 6, 7};
        assertFalse(KeyPair.fromBip39Seed("bip39-seed", 1).verify(data, signature));
    }
}
